"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["71509"],{22002(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.modalidade_selecionada.cota_reservada_exige_cascata","status":422,"titulo":"Modalidade de cota reservada deve seguir a cascata legal"},"descricao":{"codigo":"uniplus.selecao.modalidade_selecionada.cota_reservada_exige_cascata","requisitos":[],"oQueAconteceu":["Uma modalidade selecionada tem `naturezaLegal: COTA_RESERVADA` (\xe9 uma das\\nsub-reservas da Lei 12.711) mas declara `regraRemanejamento` diferente de\\n`SEGUE_ORDEM_DE_REMANEJAMENTO`. Para modalidades de cota reservada, a lei j\xe1 fixa para onde\\nas vagas ociosas v\xe3o \u2014 a sequ\xeancia ordenada de destinos e o destino final\\n(cascata legal, configurada \xe0 parte) \u2014,\\ne essa n\xe3o \xe9 uma escolha administrativa que o cadastro possa substituir por\\n`DESTINO_UNICO` ou `CRUZADO`.","Natureza legal (`COTA_RESERVADA`, entre outras) descreve **o que** a\\nmodalidade \xe9 perante a lei; regra de remanejamento descreve **o que\\nacontece** com as vagas ociosas dela. Este c\xf3digo \xe9 a ponte entre as duas: a\\nprimeira restringe os valores v\xe1lidos da segunda. Nesse caso, os par\xe2metros do remanejamento n\xe3o s\xe3o conferidos. Esta recusa sai junto com as demais recusas da modalidade; corrija todas antes de selecionar de novo.","**`naturezaLegal` e `regraRemanejamento` n\xe3o v\xeam do corpo do pedido da defini\xe7\xe3o de\\ndistribui\xe7\xe3o de vagas** \u2014 s\xe3o copiados do cadastro de modalidades de\\nConfigura\xe7\xe3o, no momento em que a modalidade \xe9 selecionada.\\nO pr\xf3prio cadastro j\xe1 impede esta incoer\xeancia na\\nescrita, tanto na cria\xe7\xe3o quanto na atualiza\xe7\xe3o; pela defini\xe7\xe3o de\\ndistribui\xe7\xe3o de vagas, este c\xf3digo s\xf3 aparece se a modalidade estiver\\ngravada no cadastro de um jeito que contorna essa valida\xe7\xe3o.","Este c\xf3digo tamb\xe9m aparece na **retifica\xe7\xe3o em ato \xfanico**: antes de\\ncongelar a vers\xe3o nova, o sistema l\xea as vers\xf5es j\xe1 publicadas do processo,\\ne essa leitura recria cada modalidade selecionada a partir do que foi\\ncongelado \u2014 a mesma cria\xe7\xe3o \xe9 conferida de novo."],"comoResolver":["O v\xednculo incoerente n\xe3o est\xe1 no corpo do pedido que voc\xea enviou \u2014 est\xe1 na\\nmodalidade cadastrada em Configura\xe7\xe3o. Corrija l\xe1: para uma modalidade de\\ncota reservada, `remanejamento.regra` precisa ser `SEGUE_ORDEM_DE_REMANEJAMENTO`, com a\\ncascata legal correspondente configurada; se a inten\xe7\xe3o era uma modalidade\\nsem v\xednculo com a Lei 12.711, reveja a `naturezaLegal` cadastrada.","Se o erro apareceu na retifica\xe7\xe3o em ato \xfanico, o problema tamb\xe9m n\xe3o est\xe1\\nno que foi enviado agora \u2014 est\xe1 em uma vers\xe3o j\xe1 publicada, que reflete\\numa modalidade j\xe1 incoerente no momento em que foi selecionada."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Modalidade selecionada"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);